function slugify(text) {
  return encodeURIComponent(text);
}

// Border radius for the admin-selectable button shape style.
function btnRadius(shape) {
  if (shape === "square") return "4px";
  if (shape === "rounded") return "12px";
  return "9999px"; // pill (default)
}

// Returns a product's category list. New products store an array in `cats`
// (so one product can appear in several categories). Older products only
// have a single `cat` string — fall back to that so nothing breaks.
function productCats(p) {
  if (p.cats && p.cats.length > 0) return p.cats;
  if (p.cat) return [p.cat];
  return [];
}

function getYoutubeId(url) {
  if (!url) return null;
  const m = url.match(/(?:youtube\.com\/(?:watch\?v=|shorts\/|embed\/)|youtu\.be\/)([a-zA-Z0-9_-]{6,})/);
  return m ? m[1] : null;
}

// Sends an email notification (via EmailJS, no backend needed) whenever a
// new order is placed. Fails silently if EmailJS isn't configured yet, so
// checkout never breaks because of this.
async function sendOrderEmail(order) {
  const isConfigured = [EMAILJS_SERVICE_ID, EMAILJS_TEMPLATE_ID, EMAILJS_PUBLIC_KEY].every(
    (v) => v && !v.startsWith("__")
  );
  if (!isConfigured) return;
  const itemsText = order.items
    .map((it) => `${it.title} (${it.size}/${it.color}) × ${it.qty} — ৳${it.price * it.qty}`)
    .join("\n");
  try {
    await fetch("https://api.emailjs.com/api/v1.0/email/send", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        service_id: EMAILJS_SERVICE_ID,
        template_id: EMAILJS_TEMPLATE_ID,
        user_id: EMAILJS_PUBLIC_KEY,
        template_params: {
          order_id: order.id,
          customer_name: order.name,
          customer_phone: order.phone,
          customer_address: order.address,
          delivery_area: order.area === "dhaka" ? "ঢাকার ভেতরে" : "ঢাকার বাইরে",
          payment: order.paymentMethod === "bkash" ? `বিকাশ (TrxID: ${order.trxId || "N/A"})` : "ক্যাশ অন ডেলিভারি",
          items: itemsText,
          subtotal: order.subtotal,
          delivery_charge: order.deliveryCharge,
          total: order.total,
        },
      }),
    });
  } catch (e) {
    // Silently ignore — order should still succeed even if the email fails.
  }
}

function Taka({ amount }) {
  return <span>৳{amount.toLocaleString("en-IN")}</span>;
}

// Computes the final price for a specific size/color combination.
// If a size has its own explicit sell/special price set in the admin panel
// (p.sizePricing[size]), that is used as the base instead of the product's
// default price. Any per-color adjustment (+/-) is then added on top.
function getVariantPrice(p, size, color) {
  let base = p.discount && p.discount > 0 && p.discount < p.price ? p.discount : p.price;
  const sp = p.sizePricing && p.sizePricing[size];
  if (sp && (sp.price || sp.discount)) {
    base = sp.discount && sp.discount > 0 && sp.discount < sp.price ? sp.discount : sp.price;
  }
  const colorAdj = (p.colorAdjust && p.colorAdjust[color]) || 0;
  return Math.max(0, base + colorAdj);
}

// Returns the "original" (pre-discount) price to show struck-through, for a
// given size selection — the size's own sell price if set, else the product's.
function getVariantOriginalPrice(p, size) {
  const sp = p.sizePricing && p.sizePricing[size];
  if (sp && sp.price) return sp.price;
  return p.price;
}

function useHashRoute() {
  const [hash, setHash] = useState(window.location.hash || "#/");
  useEffect(() => {
    const onChange = () => {
      setHash(window.location.hash || "#/");
      window.scrollTo(0, 0);
    };
    window.addEventListener("hashchange", onChange);
    return () => window.removeEventListener("hashchange", onChange);
  }, []);
  const navigate = useCallback((h) => {
    window.location.hash = h;
    window.scrollTo(0, 0);
  }, []);
  return [hash, navigate];
}

function ProductCard({ p, onOpen, onAdd, btnColor, btnShape, addCartLabel }) {
  const hasDiscount = p.discount && p.discount > 0 && p.discount < p.price;
  const discountPct = hasDiscount ? Math.round(((p.price - p.discount) / p.price) * 100) : 0;
  const firstColorImg = p.colorImages && Object.values(p.colorImages)[0];
  const imgSrc = (p.images && p.images.length > 0) ? p.images[0] : (firstColorImg || `https://picsum.photos/seed/${p.seed || p.id}/400/500`);
  const outOfStock = p.inStock === false;
  return (
    <div className="rounded-2xl overflow-hidden shadow-sm relative" style={{ background: PALETTE.card }}>
      <div className="aspect-[4/5] overflow-hidden cursor-pointer relative" onClick={() => onOpen(p)}>
        <img src={imgSrc} alt={p.title} loading="lazy" className="w-full h-full object-cover" style={outOfStock ? { filter: "grayscale(60%)", opacity: 0.7 } : undefined} />
        {outOfStock && (
          <span className="absolute top-2 left-2 text-[10px] font-semibold px-2 py-0.5 rounded-full" style={{ background: "#C0392B", color: "#fff" }}>
            স্টক নেই
          </span>
        )}
        {!outOfStock && hasDiscount && (
          <span className="absolute top-2 right-2 text-[10px] font-bold px-2 py-0.5 rounded-full" style={{ background: PALETTE.orange, color: "#fff" }}>
            {discountPct}% ছাড়
          </span>
        )}
        {!outOfStock && p.codEnabled === false && (
          <span className="absolute bottom-2 left-2 text-[10px] font-semibold px-2 py-0.5 rounded-full" style={{ background: "#E2136E", color: "#fff" }}>
            শুধু বিকাশ পেমেন্ট
          </span>
        )}
      </div>
      <div className="p-3">
        <h3 className="font-semibold text-[14px] leading-snug cursor-pointer" onClick={() => onOpen(p)}>{p.title}</h3>
        <div className="mt-1 flex items-center gap-2">
          <span className="font-bold text-sm" style={{ color: PALETTE.blue }}>
            <Taka amount={hasDiscount ? p.discount : p.price} />
          </span>
          {hasDiscount && (
            <span className="text-xs line-through" style={{ color: "#A9B8C5" }}>
              <Taka amount={p.price} />
            </span>
          )}
        </div>
        <button
          onClick={() => !outOfStock && onAdd(p)}
          disabled={outOfStock}
          className="mt-2 w-full text-xs font-semibold px-3 py-1.5"
          style={outOfStock ? { background: "#D8C9B8", color: "#7A6A58", cursor: "not-allowed", borderRadius: btnRadius(btnShape) } : { background: btnColor || PALETTE.blue, color: "#fff", borderRadius: btnRadius(btnShape) }}
        >
          {outOfStock ? "OUT OF STOCK" : (addCartLabel || "Add to cart")}
        </button>
      </div>
    </div>
  );
}

// Products are stored across multiple keys ("products_0", "products_1", ...)
// instead of one single key, because each storage key has a size ceiling.
// This groups products into chunks that each stay safely under that ceiling,
// so the shop can keep adding products without hitting a hard wall.
const PRODUCT_CHUNK_MAX_BYTES = 3_800_000;
function splitProductsIntoChunks(products) {
  const chunks = [];
  let current = [];
  let currentSize = 2;
  for (const p of products) {
    const size = JSON.stringify(p).length + 1;
    if (currentSize + size > PRODUCT_CHUNK_MAX_BYTES && current.length > 0) {
      chunks.push(current);
      current = [];
      currentSize = 2;
    }
    current.push(p);
    currentSize += size;
  }
  chunks.push(current); // always at least one chunk, even if empty
  return chunks;
}

